[{"location":"#JuDO.jl","page":"Home","title":"JuDO.jl","text":"Julia for Dynamic Optimization\n\nJuDO is a domain-specific modeling language for dynamic optimization. It extends the syntax of JuMP.jl to support infinite-dimensional optimization variables and differential equations.","category":"section"},{"location":"#Installation","page":"Home","title":"Installation","text":"using Pkg\nPkg.add(\"JuDO\")","category":"section"},{"location":"#Quick-Start","page":"Home","title":"Quick Start","text":"using JuDO\n\n# Your example here","category":"section"},{"location":"#API-Reference","page":"Home","title":"API Reference","text":"","category":"section"},{"location":"#JuDO.DynModel-Tuple","page":"Home","title":"JuDO.DynModel","text":"DynModel <: Abstract_Dynamic_Model\n\nStoring, displaying the information of the model\n\n\n\n\n\n","category":"method"},{"location":"#JuDO.dyn_value-Tuple{JuMP.Model, JuDO.DynamicVarRef}","page":"Home","title":"JuDO.dyn_value","text":"value(m::JuMP.Model, var::DynamicVarRef)\nGet the value of a dynamic variable.\n\n\n\n\n\n","category":"method"},{"location":"#JuDO.get_solutions-Tuple{JuMP.Model}","page":"Home","title":"JuDO.get_solutions","text":"get_solutions(m::JuMP.Model)\n\nReturn a dictionary mapping dynamic variable names to their solutions.\n\n\n\n\n\n","category":"method"},{"location":"#JuDO.integral-Tuple{JuMP.AbstractJuMPScalar}","page":"Home","title":"JuDO.integral","text":"JuMP.integral(expr::JuMP.AbstractJuMPScalar, phase::Int) -> Integral\n\nCreates an integral representation for the given expression and phase.\n\n\n\n\n\n","category":"method"},{"location":"#JuDO.objective_has_measures-Tuple{JuMP.Model}","page":"Home","title":"JuDO.objective_has_measures","text":"objective_has_measures(model::JuMP.Model) -> Bool\n\nReturns true if the objective function contains any measure variables.\n\n\n\n\n\n","category":"method"},{"location":"#JuDO.optimize!-Tuple{JuMP.Model}","page":"Home","title":"JuDO.optimize!","text":"optimize!(m::JuMP.Model)\nOptimize the model.\n\n\n\n\n\n","category":"method"},{"location":"#JuDO.phase_final-Tuple{JuDO.PhaseVarRef}","page":"Home","title":"JuDO.phase_final","text":"phase_final(t::PhaseVarRef)\n\nReturns the final time of the phase t. \n\nIf the final time is fixed (e.g., final(t) == 10), returns that value.\nIf the final time is free/optimized (e.g., final(t) <= 10), queries the solver for the result.\n\n\n\n\n\n","category":"method"},{"location":"#JuDO.phase_initial-Tuple{JuDO.PhaseVarRef}","page":"Home","title":"JuDO.phase_initial","text":"phase_initial(t::PhaseVarRef)\n\nReturns the initial time of the phase t defined in the model.\n\n\n\n\n\n","category":"method"},{"location":"#JuDO.set_intervals-Tuple{JuMP.Model, Any}","page":"Home","title":"JuDO.set_intervals","text":"set_intervals(m::JuMP.Model, intervals::AbstractIntervals)\nSet the intervals for the model.\n\n\n\n\n\n","category":"method"},{"location":"#JuDO.to_NDF","page":"Home","title":"JuDO.to_NDF","text":"to_NDF(f::AbstractDynamicFunction)\n\nConvert an AbstractDynamicFunction into its NonlinearDynamicFunction equivalent.\n\nThis function builds a nested expression tree to represent the input function.\n\n\n\n\n\n","category":"function"},{"location":"#JuDO.warmstart!-Tuple{JuMP.Model, DynOptInterface.AbstractDynamicSolution, JuDO.DynamicVarRef}","page":"Home","title":"JuDO.warmstart!","text":"warmstart!(m::DynModel, interpolant::DOI.AbstractDynamicSolution, var::DynamicVarRef)\nset the interpolant for a dynamic variable in the model\n\n\n\n\n\n","category":"method"},{"location":"#JuMP.build_variable-Tuple{Function, JuMP.VariableInfo, DefinedOn}","page":"Home","title":"JuMP.build_variable","text":"Extending Jump.build_variable\n\n\n\n\n\n","category":"method"}]
